import { Ionicons } from "@expo/vector-icons";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { useRouter } from "expo-router";
import { ActivityIndicator, Image, Pressable, StyleSheet, Text, View } from "react-native";
import { ModuleCard } from "../../ui/ModuleCard";
import { Screen } from "../../ui/Screen";
import { colors, radius, spacing } from "../../ui/tokens";
import { firebaseAuth } from "../auth/firebase";
import { fallbackProductImage } from "../catalog/catalog.view-model";
import { getCategories, getVendorProducts, submitVendorProduct } from "../catalog/catalog.api";

export function VendorProductDetailScreen({ id }: { id: string }) {
  const router = useRouter();
  const user = firebaseAuth?.currentUser ?? null;
  const cache = useQueryClient();
  const products = useQuery({ queryKey: ["vendor", "products"], queryFn: () => getVendorProducts(user!), enabled: Boolean(user) });
  const categories = useQuery({ queryKey: ["catalog", "categories"], queryFn: getCategories });
  const product = products.data?.find((item) => item.id === id);
  const submit = useMutation({ mutationFn: () => submitVendorProduct(user!, id), onSuccess: () => cache.invalidateQueries({ queryKey: ["vendor", "products"] }) });
  if (products.isLoading) return <Screen title="Product details"><ActivityIndicator color={colors.primary} /></Screen>;
  if (!product) return <Screen title="Product unavailable" description="This listing could not be found in your seller catalog."><Pressable onPress={() => router.replace("/vendor/products")} style={styles.primary}><Text style={styles.primaryText}>Back to products</Text></Pressable></Screen>;
  const category = categories.data?.find((item) => item.id === product.categoryId)?.name ?? "Unknown category";
  const editable = ["DRAFT", "REJECTED"].includes(product.status);
  const stock = product.variants.reduce((sum, item) => sum + item.availableQuantity, 0);
  const checks = [{ label: "Product name", pass: product.name.length >= 3 }, { label: "Description", pass: Boolean(product.description?.trim()) }, { label: "Brand", pass: Boolean(product.brand?.trim()) }, { label: "Product media", pass: product.media.length > 0 }, { label: "Sellable variant", pass: product.variants.some((item) => item.active && Number(item.price.amountMinor) > 0) }, { label: "Available stock", pass: stock > 0 }];
  return <Screen eyebrow="PRODUCT 360" title={product.name} description="Review listing quality, variants, stock and moderation status.">
    <View style={styles.toolbar}><Pressable onPress={() => router.replace("/vendor/products")} style={styles.back}><Ionicons color={colors.primary} name="arrow-back" size={18} /><Text style={styles.backText}>All products</Text></Pressable><View style={styles.actions}>{editable ? <Pressable onPress={() => router.push(`/vendor/products/edit/${id}` as never)} style={styles.outline}><Ionicons color={colors.primary} name="create-outline" size={17} /><Text style={styles.outlineText}>Edit product</Text></Pressable> : null}{editable ? <Pressable disabled={submit.isPending} onPress={() => submit.mutate()} style={styles.primary}><Text style={styles.primaryText}>{submit.isPending ? "Submitting…" : "Submit for approval"}</Text></Pressable> : null}</View></View>
    <View style={styles.layout}><View style={styles.media}><Image source={{ uri: product.media[0]?.url || product.thumbnailUrl || fallbackProductImage }} style={styles.image} />{!product.media.length ? <View style={styles.mediaNotice}><Ionicons color={colors.warning} name="image-outline" size={17} /><Text style={styles.mediaNoticeText}>No product media uploaded</Text></View> : null}</View><View style={styles.summary}><View style={styles.statusRow}><Text style={styles.status}>{product.status}</Text><Text style={styles.version}>VERSION {product.version}</Text></View><Text style={styles.name}>{product.name}</Text><Text style={styles.meta}>{product.brand || "No brand"} · {category}</Text><Text style={styles.price}>৳{(Number(product.minimumPrice.amountMinor) / 100).toLocaleString("en-BD")}</Text><Text style={styles.description}>{product.description || "No product description has been added."}</Text><View style={styles.summaryStats}><Stat label="Variants" value={String(product.variants.length)} /><Stat label="Available" value={String(stock)} /><Stat label="Reviews" value={String(product.reviewCount)} /><Stat label="Rating" value={product.rating.toFixed(1)} /></View></View></View>
    <View style={styles.twoColumns}><ModuleCard title="Listing quality" meta={`${checks.filter((item) => item.pass).length}/${checks.length} checks passed`}>{checks.map((check) => <View key={check.label} style={styles.check}><Ionicons color={check.pass ? colors.success : colors.warning} name={check.pass ? "checkmark-circle" : "alert-circle"} size={20} /><Text style={styles.checkLabel}>{check.label}</Text><Text style={[styles.checkState, check.pass && styles.checkPass]}>{check.pass ? "READY" : "NEEDS ATTENTION"}</Text></View>)}</ModuleCard><ModuleCard title="Moderation timeline" meta="Listing status and publication lifecycle"><Timeline active label="Draft created" /><Timeline active={product.status !== "DRAFT"} label="Submitted for review" /><Timeline active={product.status === "APPROVED"} label="Approved and published" /><Timeline active={product.status === "REJECTED"} danger label="Changes requested" /></ModuleCard></View>
    <ModuleCard title="Variants" meta="Pricing and current sellable stock">{product.variants.map((variant) => <View key={variant.id} style={styles.variant}><View style={styles.variantIcon}><Ionicons color={colors.primary} name="pricetag-outline" size={20} /></View><View style={styles.flex}><Text style={styles.variantName}>{variant.title}</Text><Text style={styles.variantMeta}>{variant.sku} · Version {variant.version}</Text></View><View><Text style={styles.variantPrice}>৳{(Number(variant.price.amountMinor) / 100).toLocaleString("en-BD")}</Text><Text style={styles.variantStock}>{variant.availableQuantity} available</Text></View></View>)}<Pressable onPress={() => router.push("/vendor/inventory")} style={styles.inventory}><Text style={styles.inventoryText}>Open inventory management →</Text></Pressable></ModuleCard>{submit.error ? <Text style={styles.error}>{submit.error.message}</Text> : null}
  </Screen>;
}

function Stat({ label, value }: { label: string; value: string }) { return <View style={styles.stat}><Text style={styles.statValue}>{value}</Text><Text style={styles.statLabel}>{label}</Text></View>; }
function Timeline({ active, danger, label }: { active?: boolean; danger?: boolean; label: string }) { return <View style={styles.timeline}><View style={[styles.timelineDot, active && styles.timelineActive, danger && active && styles.timelineDanger]} /> <Text style={[styles.timelineLabel, active && styles.timelineLabelActive]}>{label}</Text></View>; }
const styles = StyleSheet.create({ flex: { flex: 1 }, toolbar: { alignItems: "center", flexDirection: "row", flexWrap: "wrap", gap: spacing.md, justifyContent: "space-between" }, back: { alignItems: "center", flexDirection: "row", gap: 6 }, backText: { color: colors.primary, fontWeight: "900" }, actions: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, outline: { alignItems: "center", borderColor: colors.primary, borderRadius: radius.md, borderWidth: 1, flexDirection: "row", gap: 6, minHeight: 44, paddingHorizontal: spacing.md }, outlineText: { color: colors.primary, fontWeight: "900" }, primary: { alignItems: "center", backgroundColor: colors.primary, borderRadius: radius.md, justifyContent: "center", minHeight: 44, paddingHorizontal: spacing.md }, primaryText: { color: colors.surface, fontWeight: "900" }, layout: { alignItems: "stretch", flexDirection: "row", flexWrap: "wrap", gap: spacing.lg }, media: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderWidth: 1, minWidth: 290, overflow: "hidden", width: "42%" }, image: { aspectRatio: 1.15, backgroundColor: "#f8fafc", width: "100%" }, mediaNotice: { alignItems: "center", backgroundColor: "#fffbeb", flexDirection: "row", gap: 6, padding: spacing.sm }, mediaNoticeText: { color: colors.warning, fontSize: 10, fontWeight: "800" }, summary: { backgroundColor: colors.surface, borderColor: colors.border, borderRadius: radius.xl, borderWidth: 1, flex: 1, gap: spacing.md, minWidth: 300, padding: spacing.xl }, statusRow: { alignItems: "center", flexDirection: "row", gap: spacing.sm }, status: { backgroundColor: colors.primarySoft, borderRadius: radius.pill, color: colors.primary, fontSize: 9, fontWeight: "900", overflow: "hidden", paddingHorizontal: 10, paddingVertical: 6 }, version: { color: colors.muted, fontSize: 9, fontWeight: "900" }, name: { color: colors.text, fontSize: 27, fontWeight: "900" }, meta: { color: colors.muted }, price: { color: colors.accent, fontSize: 25, fontWeight: "900" }, description: { color: colors.text, lineHeight: 21 }, summaryStats: { flexDirection: "row", flexWrap: "wrap", gap: spacing.sm }, stat: { backgroundColor: "#f8fafc", borderRadius: radius.md, flex: 1, minWidth: 80, padding: spacing.sm }, statValue: { color: colors.text, fontSize: 16, fontWeight: "900" }, statLabel: { color: colors.muted, fontSize: 9, marginTop: 2 }, twoColumns: { alignItems: "flex-start", flexDirection: "row", flexWrap: "wrap", gap: spacing.md }, check: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.sm, minHeight: 46 }, checkLabel: { color: colors.text, flex: 1, fontWeight: "800" }, checkState: { color: colors.warning, fontSize: 8, fontWeight: "900" }, checkPass: { color: colors.success }, timeline: { alignItems: "center", flexDirection: "row", gap: spacing.sm, minHeight: 40 }, timelineDot: { backgroundColor: "#cbd5e1", borderRadius: radius.pill, height: 11, width: 11 }, timelineActive: { backgroundColor: colors.success }, timelineDanger: { backgroundColor: colors.danger }, timelineLabel: { color: colors.muted }, timelineLabelActive: { color: colors.text, fontWeight: "800" }, variant: { alignItems: "center", borderBottomColor: colors.border, borderBottomWidth: 1, flexDirection: "row", gap: spacing.md, paddingVertical: spacing.md }, variantIcon: { alignItems: "center", backgroundColor: colors.primarySoft, borderRadius: radius.md, height: 42, justifyContent: "center", width: 42 }, variantName: { color: colors.text, fontWeight: "900" }, variantMeta: { color: colors.muted, fontSize: 10, marginTop: 3 }, variantPrice: { color: colors.text, fontWeight: "900", textAlign: "right" }, variantStock: { color: colors.success, fontSize: 9, marginTop: 3, textAlign: "right" }, inventory: { alignItems: "center", paddingTop: spacing.md }, inventoryText: { color: colors.primary, fontWeight: "900" }, error: { color: colors.danger } });
